#define ASM_FILE
#include "multiboot.h"

#define FLAGS MULTIBOOT_PAGE_ALIGN | MULTIBOOT_MEMORY_INFO

/* generated by offsets.c */
#define MMMT_SIZE_OFFSET 0
#define MMMT_ADDR_OFFSET 4
#define MMMT_LEN_OFFSET 12
#define MMMT_TYPE_OFFSET 20

#define MBD_FLAGS_OFFSET 0
#define MBD_MMAP_LEN_OFFSET 44
#define MBD_MMAP_ADDR_OFFSET 48

.section .multiboot.data, "aw"
	.align 4
	.long MULTIBOOT_HEADER_MAGIC
	.long FLAGS
	.long -(MULTIBOOT_HEADER_MAGIC + FLAGS) /* checksum */

invalid_magic_number:
	.asciz "Invalid magic number.\n"

invalid_memory_map:
	.asciz "Invalid memory map passed by bootloader.\n"

mmap_string:
	.asciz "Start Addr: 0x%x, Length: 0x%x, Size: 0x%x, Type: %d\n"

.section .boot_stack, "aw", @nobits
stack_bottom:
	.skip 0x4000
stack_top:

.section .bss, "aw", @nobits
	.align 0x1000
boot_page_directory:
	.align 0x1000
boot_page_table:
	.skip 0x1000

.section .multiboot.text, "a"
.globl _start
.type _start, @function
_start:
	movl $0x00000000, %esi
	movl $(boot_page_table - 0xC0000000), %edi
	movl $1023, %ecx

/*
 * map from start of physical memory to end of kernel
 */
1:
	cmpl $(_kernel_end - 0xC0000000), %esi
	jge 2f

	movl %esi, %edx
	orl $0x03, %edx /* present, writable */
	movl %edx, (%edi)

	addl $0x1000, %esi
	addl $4, %edi
	loop 1b

2:
	/* identity mapping */
	movl $(boot_page_table - 0xC0000000 + 0x03), boot_page_directory - 0xC0000000
	movl $(boot_page_table - 0xC0000000 + 0x03), boot_page_directory - 0xC0000000 + 768 * 4

	movl $(boot_page_directory - 0xC0000000), %ecx
	movl %ecx, %cr3

	movl %cr0, %ecx
	orl $0x80010000, %ecx
	movl %ecx, %cr0

	lea 3f, %ecx
	jmp *%ecx

.section .text
	movl $stack_top, %esp

3:
	cmpl $MULTIBOOT_BOOTLOADER_MAGIC, %eax
	je 1f

	cli
	pushl $invalid_magic_number
	call printk
	hlt
1:
	testl $(1 << 6), MBD_FLAGS_OFFSET(%ebx)
	jne 1f

	cli
	pushl $invalid_memory_map
	call printk
	hlt

1:
	xorl %esi, %esi
	movl MBD_MMAP_ADDR_OFFSET(%ebx), %edi
	movl MBD_MMAP_LEN_OFFSET(%ebx), %ebx

2:
	leal (%edi, %esi, 1), %eax

/*
	pushl MMMT_TYPE_OFFSET(%eax)
	pushl MMMT_SIZE_OFFSET(%eax)
	pushl MMMT_LEN_OFFSET(%eax)
	pushl MMMT_ADDR_OFFSET(%eax)
	pushl $mmap_string
	call printk
	addl $20, %esp
*/

	addl $24, %esi
	cmpl %ebx, %esi
	jb 2b


	movl $0x00000002, boot_page_directory

	movl %cr3, %ecx
	movl %ecx, %cr3

	movl $stack_top, %esp
	call kernel_main

	cli
1:
	hlt
	jmp 1b
